//! The tag JSON API end to end through the router, without a network:
//! an in-memory repository with the same optimistic locking as SQL and,
//! for this global resource, an access policy that lets every request in
//! (the generated `DenyAll` default is tested last). Every response is also
//! checked against the OpenAPI document.
//! Generated by `forge generate resource` (and `forge generate scaffold`).

use std::error::Error;
use std::sync::{Arc, Mutex, MutexGuard};

use app::adapters::http::api_access::{ApiGlobalAccess, DenyAll};
use app::application::ports::tag_repository::{TagPage, TagRepository, TagStoreError};
use app::application::use_cases::tags::TagService;
use app::domain::entities::tag::{Tag, TagId};
use async_trait::async_trait;
use forge::core::Version;
use forge::http::{HeaderMap, HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::security::Permission;
use forge::tenancy::BearerDenied;
use serde_json::{Value, json};

type TestResult = Result<(), Box<dyn Error>>;

/// A body every rule accepts.
const VALID: &str = r#"{"label": "Example label", "active": true}"#;
/// A body with one value that breaks a rule, and the code of its refusal.
const INVALID: &str = r#"{"label": " ", "active": true}"#;
const INVALID_CODE: &str = "validation_failed";

/// Tags in memory, with the same optimistic locking as the SQL
/// repository.
#[derive(Default)]
struct InMemoryTags {
    rows: Mutex<Vec<Tag>>,
}

impl InMemoryTags {
    fn rows(&self) -> Result<MutexGuard<'_, Vec<Tag>>, TagStoreError> {
        self.rows.lock().map_err(|_| TagStoreError::Corrupt)
    }
}

#[async_trait]
impl TagRepository for InMemoryTags {
    async fn find(&self, id: TagId) -> Result<Option<Tag>, TagStoreError> {
        Ok(self
            .rows()?
            .iter()
            .find(|stored| stored.id() == id)
            .cloned())
    }

    async fn page(&self, after: Option<TagId>, limit: u16) -> Result<TagPage, TagStoreError> {
        let mut tags: Vec<Tag> = self
            .rows()?
            .iter()
            .filter(|stored| after.is_none_or(|after| stored.id() > after))
            .cloned()
            .collect();
        tags.sort_by_key(Tag::id);
        let next = if tags.len() > usize::from(limit) {
            tags.truncate(usize::from(limit));
            tags.last().map(Tag::id)
        } else {
            None
        };
        Ok(TagPage { tags, next })
    }

    async fn insert(&self, tag: &Tag) -> Result<(), TagStoreError> {
        self.rows()?.push(tag.clone());
        Ok(())
    }

    async fn update(&self, tag: &Tag) -> Result<Version, TagStoreError> {
        let next = tag.version().next().map_err(|_| TagStoreError::Conflict)?;
        let mut rows = self.rows()?;
        let stored = rows
            .iter_mut()
            .find(|stored| stored.id() == tag.id() && stored.version() == tag.version())
            .ok_or(TagStoreError::Conflict)?;
        *stored = tag.clone().with_version(next);
        Ok(next)
    }

    async fn delete(&self, id: TagId, expected: Version) -> Result<(), TagStoreError> {
        let mut rows = self.rows()?;
        let before = rows.len();
        rows.retain(|stored| !(stored.id() == id && stored.version() == expected));
        if rows.len() == before {
            Err(TagStoreError::Conflict)
        } else {
            Ok(())
        }
    }
}

/// Lets every request in; stands for the policy the application chooses.
struct AllowAll;

#[async_trait]
impl ApiGlobalAccess for AllowAll {
    async fn authorize(&self, _: &Request, _: &Permission) -> Result<(), BearerDenied> {
        Ok(())
    }
}

/// The router with only the tag API, checked against its OpenAPI
/// document.
struct Harness {
    router: Router,
}

impl Harness {
    fn new() -> Result<Self, Box<dyn Error>> {
        Self::with_access(Arc::new(AllowAll))
    }

    fn with_access(access: Arc<dyn ApiGlobalAccess>) -> Result<Self, Box<dyn Error>> {
        let mut router = Router::new();
        app::adapters::http::tags_api::routes(
            &mut router,
            TagService::new(Arc::new(InMemoryTags::default())),
            access,
        )?;
        let document = router.openapi(&forge::openapi::Info::new("app", "0.0.0"))?;
        router.layer(forge::openapi::CheckResponses::new(document, |failure| {
            panic!("{failure}")
        }));
        Ok(Self { router })
    }

    async fn send(
        &self,
        method: Method,
        path: &str,
        authorization: Option<&str>,
        body: Option<&str>,
    ) -> Result<Response, Box<dyn Error>> {
        let mut headers = HeaderMap::new();
        if let Some(authorization) = authorization {
            headers.insert(header::AUTHORIZATION, HeaderValue::from_str(authorization)?);
        }
        if body.is_some() {
            headers.insert(
                header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
        }
        let request = Request::new_for_test(
            method,
            path.parse()?,
            headers,
            body.unwrap_or_default().to_owned().into(),
            "127.0.0.1:4000".parse()?,
            forge::core::Id::<Request>::new().into_uuid(),
        );
        Ok(self.router.dispatch(request).await)
    }
}

fn json_body(response: &Response) -> Value {
    serde_json::from_slice(response.body()).unwrap_or(Value::Null)
}

fn id_of(response: &Response) -> Result<String, Box<dyn Error>> {
    Ok(json_body(response)["id"]
        .as_str()
        .ok_or("the response has an id")?
        .to_owned())
}

#[tokio::test]
async fn create_show_list_update_and_delete() -> TestResult {
    let harness = Harness::new()?;
    let token = None;

    let created = harness
        .send(Method::POST, "/v1/tags", token, Some(VALID))
        .await?;
    assert_eq!(
        created.status(),
        StatusCode::CREATED,
        "{:?}",
        json_body(&created)
    );
    let id = id_of(&created)?;
    let path = format!("/v1/tags/{id}");
    assert_eq!(
        created
            .headers()
            .get(header::LOCATION)
            .and_then(|value| value.to_str().ok()),
        Some(path.as_str())
    );
    assert_eq!(json_body(&created)["version"], 1);
    assert_eq!(json_body(&created)["label"], json!("Example label"));

    let shown = harness.send(Method::GET, &path, token, None).await?;
    assert_eq!(shown.status(), StatusCode::OK);
    assert_eq!(json_body(&shown), json_body(&created));

    let listed = harness.send(Method::GET, "/v1/tags", token, None).await?;
    assert_eq!(listed.status(), StatusCode::OK);
    assert_eq!(json_body(&listed)["items"][0]["id"], json!(id));
    assert_eq!(json_body(&listed)["next_cursor"], Value::Null);

    let changes = json!({"version": 1, "label": "Changed"}).to_string();
    let updated = harness
        .send(Method::PATCH, &path, token, Some(&changes))
        .await?;
    assert_eq!(
        updated.status(),
        StatusCode::OK,
        "{:?}",
        json_body(&updated)
    );
    assert_eq!(json_body(&updated)["version"], 2);
    assert_eq!(json_body(&updated)["label"], json!("Changed"));

    let deleted = harness
        .send(Method::DELETE, &format!("{path}?version=2"), token, None)
        .await?;
    assert_eq!(deleted.status(), StatusCode::NO_CONTENT);
    let gone = harness.send(Method::GET, &path, token, None).await?;
    assert_eq!(gone.status(), StatusCode::NOT_FOUND);
    assert_eq!(json_body(&gone)["code"], "tag_not_found");
    Ok(())
}

#[tokio::test]
async fn invalid_values_and_bodies_are_unprocessable() -> TestResult {
    let harness = Harness::new()?;
    let token = None;
    let invalid = harness
        .send(Method::POST, "/v1/tags", token, Some(INVALID))
        .await?;
    assert_eq!(invalid.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(json_body(&invalid)["code"], INVALID_CODE);
    for body in ["{}", "not json", r#"{"unknown": 1}"#] {
        let refused = harness
            .send(Method::POST, "/v1/tags", token, Some(body))
            .await?;
        assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY, "{body}");
        assert_eq!(json_body(&refused)["code"], "invalid_json", "{body}");
    }
    let listed = harness.send(Method::GET, "/v1/tags", token, None).await?;
    assert_eq!(json_body(&listed)["items"], json!([]), "nothing was stored");
    Ok(())
}

#[tokio::test]
async fn a_stale_version_conflicts_and_unknown_ids_are_not_found() -> TestResult {
    let harness = Harness::new()?;
    let token = None;
    let created = harness
        .send(Method::POST, "/v1/tags", token, Some(VALID))
        .await?;
    let path = format!("/v1/tags/{}", id_of(&created)?);
    let stale = json!({"version": 7}).to_string();
    let conflict = harness
        .send(Method::PATCH, &path, token, Some(&stale))
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);
    assert_eq!(json_body(&conflict)["code"], "tag_conflict");
    let conflict = harness
        .send(Method::DELETE, &format!("{path}?version=7"), token, None)
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);

    let unknown = format!("/v1/tags/{}", TagId::new());
    for method in [Method::GET, Method::PATCH] {
        let body = (method == Method::PATCH).then_some(r#"{"version": 1}"#);
        let missing = harness.send(method, &unknown, token, body).await?;
        assert_eq!(missing.status(), StatusCode::NOT_FOUND);
    }
    let malformed = harness
        .send(Method::GET, "/v1/tags/not-an-id", token, None)
        .await?;
    assert_eq!(malformed.status(), StatusCode::BAD_REQUEST);
    assert_eq!(json_body(&malformed)["code"], "invalid_id");
    Ok(())
}

#[tokio::test]
async fn the_generated_deny_all_default_refuses_every_route() -> TestResult {
    let harness = Harness::with_access(Arc::new(DenyAll))?;
    let member = format!("/v1/tags/{}", TagId::new());
    let changes = json!({"version": 1}).to_string();
    for (method, path, body) in [
        (Method::GET, "/v1/tags".to_owned(), None),
        (Method::POST, "/v1/tags".to_owned(), Some(VALID)),
        (Method::GET, member.clone(), None),
        (Method::PATCH, member.clone(), Some(changes.as_str())),
        (Method::DELETE, format!("{member}?version=1"), None),
    ] {
        let response = harness.send(method, &path, None, body).await?;
        assert_eq!(response.status(), StatusCode::FORBIDDEN, "{path}");
    }
    Ok(())
}
